const items = $input.all();
const normalizedItems = [];

function resolveModelSpec(rawToken) {
  const clean = String(rawToken || '').trim();
  if (!clean) return null;
  const lower = clean.toLowerCase();
  let provider = '';
  let model = '';

  if (clean.includes('/')) {
    const slashIdx = clean.indexOf('/');
    const rawProv = clean.slice(0, slashIdx).trim().toLowerCase();
    const modelTrim = clean.slice(slashIdx + 1).trim();

    if (rawProv === 'models' && modelTrim.toLowerCase().startsWith('gemini')) {
      provider = 'gemini';
      model = 'models/' + modelTrim;
    } else if (rawProv === 'gemini' || rawProv === 'google') {
      provider = 'gemini';
      if (!modelTrim) {
        model = 'models/gemini-3.5-flash';
      } else {
        model = modelTrim.toLowerCase().startsWith('models/')
          ? 'models/' + modelTrim.slice(7)
          : 'models/' + modelTrim;
      }
    } else if (rawProv === 'openai') {
      provider = 'openai';
      model = modelTrim || 'gpt-6-luna';
    } else if (rawProv === 'mistral' || rawProv === 'mistralai' || rawProv === 'eu-mistral') {
      provider = 'mistral';
      model = modelTrim || 'mistral-medium-latest';
    } else if (rawProv === 'glm' || rawProv === 'zai' || rawProv === 'z.ai') {
      provider = 'mistral';
      model = modelTrim || 'zai-glm-5-3';
    } else if (rawProv === 'anthropic') {
      provider = 'anthropic';
      model = modelTrim || 'claude-3-5-sonnet-20241022';
    } else {
      provider = rawProv;
      model = modelTrim;
    }
  } else {
    if (lower === 'openai') {
      provider = 'openai';
      model = 'gpt-6-luna';
    } else if (lower.startsWith('gpt-') || /^o[134](-|$)/.test(lower)) {
      provider = 'openai';
      model = clean;
    } else if (lower === 'gemini' || lower === 'google') {
      provider = 'gemini';
      model = 'models/gemini-3.5-flash';
    } else if (lower.startsWith('gemini-')) {
      provider = 'gemini';
      model = 'models/' + clean;
    } else if (lower === 'mistral' || lower === 'mistralai') {
      provider = 'mistral';
      model = 'mistral-medium-latest';
    } else if (
      lower.startsWith('mistral-')
      || lower.startsWith('pixtral-')
      || lower.startsWith('codestral-')
      || lower.startsWith('ministral-')
    ) {
      provider = 'mistral';
      model = clean;
    } else if (lower === 'glm' || lower === 'glm-5-3') {
      provider = 'mistral';
      model = 'zai-glm-5-3';
    } else if (lower === 'glm-5-3-flash') {
      provider = 'mistral';
      model = 'zai-glm-5-3-flash';
    } else if (lower.startsWith('zai-glm') || lower.startsWith('glm-')) {
      provider = 'mistral';
      model = clean;
    } else if (lower === 'anthropic') {
      provider = 'anthropic';
      model = 'claude-3-5-sonnet-20241022';
    } else if (lower.startsWith('claude-')) {
      provider = 'anthropic';
      model = clean;
    } else {
      provider = lower;
      model = clean;
    }
  }

  return {
    id: model ? (provider + '/' + model) : provider,
    provider,
    model,
    eu_hosted: provider === 'mistral'
  };
}

function parseShorthand(text) {
  const result = {
    prompt: '',
    brand_name: '',
    brand_domains: [],
    competitors: [],
    target_llms: ['openai/gpt-6-luna', 'gemini/models/gemini-3.5-flash'],
    search_enabled: true
  };
  if (!text || typeof text !== 'string') return result;

  const lines = text.split(/[\n|]/);
  for (const line of lines) {
    const colonIdx = line.indexOf(':');
    if (colonIdx === -1) {
      if (!result.prompt && line.trim()) result.prompt = line.trim();
      continue;
    }
    const key = line.slice(0, colonIdx).trim().toUpperCase();
    const val = line.slice(colonIdx + 1).trim();
    if (key === 'PROMPT') {
      result.prompt = val;
    } else if (key === 'BRAND') {
      result.brand_name = val;
    } else if (key === 'DOMAINS') {
      result.brand_domains = val.split(',').map(d => d.trim().toLowerCase()).filter(Boolean);
    } else if (key === 'COMPETITORS') {
      result.competitors = val.split(',').map(c => {
        const match = c.match(/^(.*?)(?:\s*\((.*?)\))?$/);
        return {
          name: match ? match[1].trim() : c.trim(),
          domain: match && match[2] ? match[2].trim().toLowerCase() : ''
        };
      }).filter(c => c.name);
    } else if (key === 'LLMS') {
      const parsedLlms = val.split(',').map(l => l.trim()).filter(Boolean);
      if (parsedLlms.length > 0) result.target_llms = parsedLlms;
    } else if (key === 'SEARCH') {
      result.search_enabled = val.toLowerCase() === 'true' || val === '1';
    }
  }
  return result;
}

function expandTargetLLMs(input, triggerSource, inputIdx) {
  if (!input || typeof input !== 'object') return [];
  const rawPrompts = Array.isArray(input.prompts)
    ? input.prompts.map(p => String(p || '').trim()).filter(Boolean)
    : [];
  const primaryPrompt = String(input.prompt || '').trim();
  const promptList = rawPrompts.length > 0 ? rawPrompts : [primaryPrompt];

  const brandName = String(input.brand_name || '').trim();
  const brandDomains = Array.isArray(input.brand_domains) ? input.brand_domains.filter(Boolean) : [];
  const competitors = (Array.isArray(input.competitors) ? input.competitors : []).map(c => {
    if (typeof c === 'string') return { name: c.trim(), domain: '' };
    if (c && typeof c === 'object') {
      return {
        name: String(c.name || c.competitor_name || '').trim(),
        domain: String(c.domain || c.competitor_domain || '').trim().toLowerCase()
      };
    }
    return null;
  }).filter(c => c && c.name);

  let searchEnabled = true;
  if (input.search_enabled !== undefined) {
    searchEnabled = typeof input.search_enabled === 'string'
      ? (input.search_enabled.toLowerCase() === 'true' || input.search_enabled === '1')
      : Boolean(input.search_enabled);
  }

  let rawTargetLLMs = input.target_llms;
  if (typeof rawTargetLLMs === 'string') {
    rawTargetLLMs = rawTargetLLMs.split(',').map(s => s.trim()).filter(Boolean);
  }
  if (!Array.isArray(rawTargetLLMs) || rawTargetLLMs.length === 0) {
    rawTargetLLMs = ['openai/gpt-6-luna', 'gemini/models/gemini-3.5-flash'];
  }

  const seenSpecs = new Set();
  const specs = [];
  for (const token of rawTargetLLMs) {
    if (token === null || token === undefined) continue;
    const spec = resolveModelSpec(String(token));
    if (spec && spec.id && !seenSpecs.has(spec.id)) {
      seenSpecs.add(spec.id);
      specs.push(spec);
    }
  }
  if (specs.length === 0) {
    specs.push(
      resolveModelSpec('openai/gpt-6-luna'),
      resolveModelSpec('gemini/models/gemini-3.5-flash')
    );
  }

  const responseMode = input.response_mode || ((input.is_async === true || input.is_async === 'true') ? 'async' : (triggerSource === 'chat' ? 'sync' : (triggerSource === 'webhook' ? 'sync' : 'async')));
  const configId = input.config_id || null;
  const userId = input.user_id || null;
  const runId = input.run_id || ('run_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9));
  const createdAt = new Date().toISOString();

  const expanded = [];
  for (let pIdx = 0; pIdx < promptList.length; pIdx++) {
    const promptText = promptList[pIdx];
    for (const spec of specs) {
      expanded.push({
        json: {
          run_id: runId,
          prompt_index: pIdx,
          config_id: configId,
          user_id: userId,
          trigger_source: triggerSource,
          response_mode: responseMode,
          prompt: promptText,
          brand_name: brandName,
          brand_domains: brandDomains,
          competitors,
          provider: spec.provider,
          selected_provider: spec.provider,
          model: spec.model,
          model_key: spec.id,
          eu_hosted: spec.eu_hosted,
          is_eu_hosted: spec.eu_hosted,
          search_enabled: searchEnabled,
          locale: input.locale || 'de-DE',
          created_at: createdAt
        },
        pairedItem: { item: inputIdx }
      });
    }
  }
  return expanded;
}

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  let raw = item && item.json ? item.json : {};
  if (!raw || typeof raw !== 'object') raw = {};
  let triggerSource = 'webhook';
  let inputData = {};

  if (raw.chatInput !== undefined) {
    triggerSource = 'chat';
    const text = String(raw.chatInput).trim();
    if (text.startsWith('{') && text.endsWith('}')) {
      try {
        inputData = JSON.parse(text);
      } catch (e) {
        inputData = parseShorthand(text);
      }
    } else {
      inputData = parseShorthand(text);
    }
  } else if (raw.jobs && Array.isArray(raw.jobs)) {
    triggerSource = 'schedule_queue';
    for (const job of (raw.jobs || []).filter(Boolean)) {
      if (job && typeof job === 'object') {
        normalizedItems.push(...expandTargetLLMs(job, triggerSource, idx));
      }
    }
    continue;
  } else if (raw.status === 'error' || raw.error) {
    continue;
  } else {
    inputData = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
    triggerSource = 'webhook';
  }

  normalizedItems.push(...expandTargetLLMs(inputData, triggerSource, idx));
}

return normalizedItems;

