const items = $input.all();
const results = [];

function extractDomainFromUrl(urlOrDomain) {
  if (!urlOrDomain || typeof urlOrDomain !== 'string') return '';
  let clean = urlOrDomain.trim();
  try {
    clean = decodeURIComponent(clean);
  } catch (_) {
    clean = clean.replace(/%2f/gi, '/').replace(/%3a/gi, ':').replace(/%40/gi, '@');
  }
  clean = clean.toLowerCase().replace(/^https?:\/\//i, '');
  const atIdx = clean.indexOf('@');
  const firstSlash = clean.indexOf('/');
  if (atIdx !== -1 && (firstSlash === -1 || atIdx < firstSlash)) {
    clean = clean.slice(atIdx + 1);
  }
  clean = clean.replace(/^www\./i, '');
  for (const sep of ['/', ':', '?', '#']) {
    const idx = clean.indexOf(sep);
    if (idx !== -1) clean = clean.slice(0, idx);
  }
  return clean.trim();
}

function matchesDomain(candidateDomain, registeredDomains) {
  if (!candidateDomain || !registeredDomains) return false;
  const regList = Array.isArray(registeredDomains) ? registeredDomains : [registeredDomains];
  const cleanCand = extractDomainFromUrl(String(candidateDomain));
  if (!cleanCand) return false;
  return regList.some(reg => {
    const cleanReg = extractDomainFromUrl(String(reg));
    return cleanReg && (cleanCand === cleanReg || cleanCand.endsWith('.' + cleanReg));
  });
}

function extractErrorInfo(data, meta) {
  if (!data || typeof data !== 'object') return null;

  if (data.error !== null && data.error !== undefined) {
    if (typeof data.error === 'string' && data.error.trim()) {
      return data.error.trim();
    }
    if (typeof data.error === 'object') {
      const msg = data.error.message || data.error.msg || data.error.description;
      if (msg) return String(msg).trim();
      return JSON.stringify(data.error);
    }
  }

  if (data.object === 'error') {
    return String(data.message || data.detail || 'Provider returned error object').trim();
  }

  if (typeof data.errorMessage === 'string' && data.errorMessage.trim()) {
    return data.errorMessage.trim();
  }

  if (data.detail && !data.choices && !data.candidates && !data.output && !data.content) {
    if (Array.isArray(data.detail)) {
      return data.detail.map(d => (d && d.msg ? d.msg : JSON.stringify(d))).join('; ');
    }
    return String(data.detail).trim();
  }

  if (typeof data.statusCode === 'number' && data.statusCode >= 400) {
    return String(data.message || data.statusMessage || ('HTTP ' + data.statusCode));
  }

  if (data.status === 'failed' || data.status === 'error') {
    return String(data.message || data.incomplete_details?.reason || 'LLM provider returned failed status');
  }

  if (
    typeof data.message === 'string'
    && data.message.trim()
    && !data.choices
    && !data.candidates
    && !data.output
    && !data.content
    && !data.raw_response_text
    && !data.raw_response
    && !data.text
    && !data.prompt
  ) {
    return data.message.trim();
  }

  const cand0 = Array.isArray(data.candidates) ? data.candidates[0] : null;
  if (
    cand0
    && ['SAFETY', 'RECITATION', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII'].includes(String(cand0.finishReason || ''))
    && (!cand0.content || !Array.isArray(cand0.content.parts) || cand0.content.parts.every(p => !p || !p.text))
  ) {
    return 'Gemini response blocked (' + cand0.finishReason + ')';
  }

  const isUntouchedDisabledAnthropic = (
    (meta.provider || data.provider) === 'anthropic'
    && data.trigger_source !== undefined
    && !data.content
    && !data.choices
    && !data.output
    && !data.candidates
    && !data.raw_response_text
    && !data.raw_response
    && !data.text
  );
  if (isUntouchedDisabledAnthropic) {
    return 'Anthropic fallback node is disabled in n8n workflow.';
  }

  return null;
}

function joinPartsText(parts) {
  if (!Array.isArray(parts)) return '';
  const nonThought = parts
    .filter(p => p && !p.thought && typeof p.text === 'string')
    .map(p => p.text);
  if (nonThought.length > 0) return nonThought.join('');
  return parts
    .filter(p => p && typeof p.text === 'string')
    .map(p => p.text)
    .join('');
}

function extractResponseText(data) {
  if (!data || typeof data !== 'object') return '';

  // 1. OpenAI Chat Completions & Mistral EU / Z.ai GLM
  if (data.choices && Array.isArray(data.choices) && data.choices[0]?.message?.content !== undefined) {
    const content = data.choices[0].message.content;
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
      return content
        .map(part => {
          if (typeof part === 'string') return part;
          if (part && typeof part.text === 'string' && (!part.type || part.type === 'text' || part.type === 'output_text')) {
            return part.text;
          }
          return '';
        })
        .join('');
    }
  }

  // 2. OpenAI Native Responses API (simplify: false)
  if (Array.isArray(data.output)) {
    const chunks = [];
    for (const block of data.output) {
      if (!block) continue;
      if (typeof block === 'string') {
        chunks.push(block);
      } else if (Array.isArray(block.content)) {
        for (const part of block.content) {
          if (typeof part === 'string') {
            chunks.push(part);
          } else if (part && typeof part.text === 'string') {
            chunks.push(part.text);
          }
        }
      } else if (typeof block.text === 'string') {
        chunks.push(block.text);
      }
    }
    if (chunks.length > 0) return chunks.join('\n').trim();
  }
  if (typeof data.output_text === 'string' && data.output_text) {
    return data.output_text;
  }
  if (typeof data.output === 'string' && data.output) {
    return data.output;
  }

  // 3. Google Gemini Native (simplify: false -> candidates[0].content.parts, or unwrapped content.parts)
  if (data.candidates && Array.isArray(data.candidates) && data.candidates[0]?.content?.parts) {
    return joinPartsText(data.candidates[0].content.parts);
  }
  if (data.content && !Array.isArray(data.content) && Array.isArray(data.content.parts)) {
    return joinPartsText(data.content.parts);
  }

  // 4. Anthropic Messages API (content[].text)
  if (data.content && Array.isArray(data.content)) {
    const texts = data.content
      .filter(c => c && typeof c.text === 'string')
      .map(c => c.text);
    if (texts.length > 0) return texts.join('');
  }

  // 5. Simplified / Direct Text Pass-through
  if (data.raw_response_text !== undefined && data.raw_response_text !== null) return String(data.raw_response_text);
  if (data.raw_response !== undefined && data.raw_response !== null) return String(data.raw_response);
  if (data.text !== undefined && data.text !== null) return String(data.text);

  return '';
}

function addCitation(citations, seenUrls, url, title, sourceType) {
  const cleanUrl = String(url || '').trim();
  if (!cleanUrl || seenUrls.has(cleanUrl)) return;
  seenUrls.add(cleanUrl);
  const domain = extractDomainFromUrl(cleanUrl);
  const cleanTitle = title ? String(title).trim() : 'Untitled';
  citations.push({
    citation_url: cleanUrl,
    citation_domain: domain,
    domain,
    citation_title: cleanTitle || 'Untitled',
    title: cleanTitle || 'Untitled',
    source_type: sourceType
  });
}

function extractCitations(data, rawText, brandDomains, competitorList) {
  const citations = [];
  const seenUrls = new Set();
  const safeCompList = (Array.isArray(competitorList) ? competitorList : []).filter(Boolean);

  // 1. Gemini Grounding Metadata Chunks (raw or unwrapped)
  const geminiChunks = data.candidates?.[0]?.groundingMetadata?.groundingChunks
    || data.groundingMetadata?.groundingChunks;
  if (Array.isArray(geminiChunks)) {
    for (const chunk of geminiChunks) {
      if (chunk && chunk.web && chunk.web.uri) {
        addCitation(citations, seenUrls, chunk.web.uri, chunk.web.title, 'grounding_metadata');
      }
    }
  }

  // 2. OpenAI Responses API url_citation annotations (and Chat Completions annotations)
  const collectAnnotations = (annotations) => {
    if (!Array.isArray(annotations)) return;
    for (const ann of annotations) {
      if (!ann || typeof ann !== 'object') continue;
      if (ann.type === 'url_citation' || ann.url_citation || ann.url) {
        const citUrl = ann.url || ann.url_citation?.url;
        const citTitle = ann.title || ann.url_citation?.title || 'Untitled';
        if (citUrl) addCitation(citations, seenUrls, citUrl, citTitle, 'openai_web_search');
      }
    }
  };
  if (Array.isArray(data.output)) {
    for (const block of data.output) {
      if (block && Array.isArray(block.content)) {
        for (const part of block.content) {
          if (part && Array.isArray(part.annotations)) {
            collectAnnotations(part.annotations);
          }
        }
      }
    }
  }
  collectAnnotations(data.choices?.[0]?.message?.annotations);

  // 3. Markdown Links in Text
  if (rawText && typeof rawText === 'string') {
    const mdRegex = /\[(.*?)\]\((https?:\/\/[^\s)]+)\)/g;
    let match;
    while ((match = mdRegex.exec(rawText)) !== null) {
      addCitation(citations, seenUrls, match[2], match[1], 'markdown_link');
    }

    // 4. Bare URLs
    const textWithoutMd = rawText.replace(/\[(.*?)\]\(https?:\/\/[^\s)]+\)/g, ' ');
    const bareRegex = /https?:\/\/(?:[a-zA-Z0-9_.-]+(?::[a-zA-Z0-9_.-]+)?@)?[a-zA-Z0-9.-]+(?::\d+)?(?:\/[^\s)]*)?/g;
    const bareMatches = textWithoutMd.match(bareRegex) || [];
    for (const rawUrl of bareMatches) {
      const cleanUrl = rawUrl.replace(/[.,;:!\])]+$/, '');
      addCitation(citations, seenUrls, cleanUrl, 'Untitled', 'bare_url');
    }
  }

  return citations.map((c, idx) => {
    const isBrand = matchesDomain(c.citation_domain, brandDomains);
    const isComp = safeCompList.some(comp => {
      const cDomain = (comp && typeof comp === 'object') ? (comp.domain || comp.competitor_domain || '') : (typeof comp === 'string' ? comp : '');
      return cDomain && matchesDomain(c.citation_domain, cDomain);
    });
    return {
      citation_index: idx + 1,
      citation_url: c.citation_url,
      citation_domain: c.citation_domain,
      domain: c.citation_domain,
      citation_title: c.citation_title,
      title: c.citation_title,
      is_brand_domain: isBrand,
      is_competitor_domain: isComp,
      source_type: c.source_type
    };
  });
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const rawPayload = (item && item.json && typeof item.json === 'object') ? item.json : {};
  let meta = {};

  try {
    if (typeof $ === 'function') {
      const normalizerNode = $('Universal Normalizer');
      if (normalizerNode) {
        meta = (normalizerNode.itemMatching && normalizerNode.itemMatching(i)?.json)
          || (normalizerNode.item && normalizerNode.item.json)
          || (normalizerNode.all && normalizerNode.all()[i]?.json)
          || (normalizerNode.first && normalizerNode.first()?.json)
          || {};
      }
    }
  } catch (_) {}

  const resolvedProvider = meta.provider || meta.selected_provider || rawPayload.provider || rawPayload.selected_provider || 'openai';
  const resolvedModel = meta.model || rawPayload.model || rawPayload.modelVersion || 'gpt-6-luna';
  const resolvedEuHosted = meta.eu_hosted !== undefined
    ? Boolean(meta.eu_hosted)
    : (resolvedProvider === 'mistral' || String(resolvedModel).includes('zai-glm'));

  const errorMessage = extractErrorInfo(rawPayload, meta);
  let rawText = extractResponseText(rawPayload);
  let status = 'completed';
  let isError = false;

  if (errorMessage) {
    isError = true;
    status = 'failed';
    rawText = 'ERROR: ' + errorMessage;
  }

  const brandDomains = meta.brand_domains || rawPayload.brand_domains || [];
  const competitors = meta.competitors || rawPayload.competitors || [];
  const extractedCitations = isError
    ? []
    : extractCitations(rawPayload, rawText, brandDomains, competitors);

  results.push({
    json: {
      ...meta,
      ...rawPayload,
      run_id: meta.run_id || rawPayload.run_id,
      config_id: meta.config_id ?? rawPayload.config_id,
      user_id: meta.user_id ?? rawPayload.user_id,
      prompt: meta.prompt !== undefined ? meta.prompt : rawPayload.prompt,
      brand_name: meta.brand_name !== undefined ? meta.brand_name : rawPayload.brand_name,
      brand_domains: brandDomains,
      provider: resolvedProvider,
      selected_provider: resolvedProvider,
      model: resolvedModel,
      model_name: resolvedModel,
      eu_hosted: resolvedEuHosted,
      is_eu_hosted: resolvedEuHosted,
      search_enabled: meta.search_enabled !== undefined ? Boolean(meta.search_enabled) : Boolean(rawPayload.search_enabled),
      status,
      is_error: isError,
      error_message: errorMessage || null,
      raw_response: rawText,
      raw_response_text: rawText,
      text: rawText,
      citations: extractedCitations,
      competitors: (Array.isArray(competitors) ? competitors : []).filter(Boolean).map(c => typeof c === 'string' ? { name: c, domain: '' } : c)
