        brand_relative_pos: null,
        brand_match_type: 'none',
        mece_category: '4_GENERIC',
        geo_quadrant: 'NONE',
        has_citations: false,
        brand_domain_cited: false,
        brand_cited: false,
        competitor_cited: false,
        diagnostics: {
          primary_quadrant: 'NONE',
          is_citation_hijack: false,
          is_parametric_blindspot: false,
          is_brand_halo_trap: false,
          is_buried_winner: false
        },
        competitors: [],
        citations: []
      }
    : calculateMetrics(text, d.brand_name || '', d.brand_domains || [], d.competitors || [], d.citations || []);

  const totalChars = metrics.character_count;
  const totalWords = metrics.word_count;
  const brandMentioned = (!isFailed && metrics.brand_mentioned) ? 1 : 0;
  const charEarliness = metrics.brand_earliness_char;
  const wordEarliness = metrics.brand_earliness_word;
  const relPosPct = metrics.brand_relative_pos;
  const brandDomainCited = (!isFailed && metrics.brand_domain_cited) ? 1 : 0;
  const competitorCited = (!isFailed && metrics.competitor_cited) ? 1 : 0;
  const meceCategory = metrics.mece_category;
  const geoQuadrant = metrics.geo_quadrant;
  const brandRecommended = !isFailed && meceCategory === '1_DIRECT_WIN';
  const resolvedProvider = d.provider || d.selected_provider || 'openai';
  const resolvedModel = d.model || 'gpt-6-luna';
  const euHosted = d.eu_hosted !== undefined
    ? Boolean(d.eu_hosted)
    : (resolvedProvider === 'mistral' || String(resolvedModel).includes('zai-glm'));

  results.push({
    json: {
      ...d,
      ...metrics,
      config_id: d.config_id || 101,
      user_id: d.user_id || 5,
      prompt: d.prompt || '',
      prompt_text: d.prompt || '',
      provider: resolvedProvider,
      model: resolvedModel,
      model_name: resolvedModel,
      eu_hosted: euHosted,
      is_eu_hosted: euHosted,
      status: isFailed ? 'failed' : 'completed',
      error_message: isFailed ? (d.error_message || text || 'LLM execution failed') : null,
      cost_credits: isFailed ? 0 : (d.cost_credits !== undefined ? d.cost_credits : 1),
      brand_name: d.brand_name || metrics.brand_name || '',
      brand_mentioned: brandMentioned,
      brand_recommended: brandRecommended,
      brand_prominence_rank: brandRecommended ? 1 : (brandMentioned ? 2 : null),
      char_earliness: charEarliness,
      brand_earliness_char: charEarliness,
      word_earliness: wordEarliness,
      brand_earliness_word: wordEarliness,
      relative_position_pct: relPosPct,
      brand_relative_pos: relPosPct,
      total_chars: totalChars,
      character_count: totalChars,
      total_words: totalWords,
      word_count: totalWords,
      mece_category: meceCategory,
      geo_quadrant: geoQuadrant,
      has_citations: !isFailed && (metrics.citations || []).length > 0 ? 1 : 0,
      brand_domain_cited: brandDomainCited,
      brand_cited: brandDomainCited,
      competitor_cited: competitorCited,
      raw_response_text: text,
      raw_response: text,
      run_duration_ms: d.run_duration_ms || 1150,
      competitors: (metrics.competitors || []).map(c => ({
        competitor_name: c.competitor_name || c.name || '',
        competitor_domain: c.competitor_domain || c.domain || null,
        mentioned: c.mentioned ? 1 : 0,
        is_mentioned: c.mentioned ? 1 : 0,
        is_cited: c.is_cited ? 1 : 0,
        char_earliness: c.char_earliness !== undefined ? c.char_earliness : null,
        earliness_char: c.char_earliness !== undefined ? c.char_earliness : null,
        word_earliness: c.word_earliness !== undefined ? c.word_earliness : null,
        earliness_word: c.word_earliness !== undefined ? c.word_earliness : null,
        relative_position_pct: c.relative_position_pct !== undefined ? c.relative_position_pct : null,
        relative_pos: c.relative_position_pct !== undefined ? c.relative_position_pct : null
      })),
      citations: metrics.citations || []
    }
  });
}

return results;

const items = $input.all();
const output = [];

for (const item of items) {
  const d = item.json;
  const isFailed = d.status === 'failed' || d.is_error === true;
  const euTag = d.eu_hosted ? ' [EU-Hosted · api.eu.mistral.ai]' : '';

  let meceBadge = '⚪';
  if (isFailed) meceBadge = '❌ (Failed Run — Excluded from KPIs)';
  else if (d.mece_category === '1_DIRECT_WIN') meceBadge = '🏆 (Direct Win)';
  else if (d.mece_category === '2_BRAND_HALO') meceBadge = '🟣 (Brand Halo)';
  else if (d.mece_category === '3_COMPETITOR_TAKEOVER') meceBadge = '🔴 (Competitor Takeover)';
  else if (d.mece_category === '4_GENERIC') meceBadge = '⚪ (Generic / Neutral)';

  let geoBadge = isFailed ? 'Execution failed' : 'Clean Visibility';
  if (!isFailed) {
    if (d.geo_quadrant === '1_CITATION_HIJACK') geoBadge = '⚠️ 1_CITATION_HIJACK (Brand in text, competitor cited)';
    else if (d.geo_quadrant === '2_PARAMETRIC_BLINDSPOT') geoBadge = '⚠️ 2_PARAMETRIC_BLINDSPOT (Domain cited, brand omitted)';
    else if (d.geo_quadrant === '3_BRAND_HALO_TRAP') geoBadge = '⚠️ 3_BRAND_HALO_TRAP (Trapped behind competitor)';
    else if (d.geo_quadrant === '4_BURIED_WINNER') geoBadge = '⚠️ 4_BURIED_WINNER (Won, but buried >50% deep)';
  }

  const brandDomains = Array.isArray(d.brand_domains) ? d.brand_domains.join(', ') : (d.brand_domains || 'N/A');
  const earlinessStr = d.brand_mentioned === 1
    ? `Wort #${d.word_earliness || d.brand_earliness_word} (${d.relative_position_pct || d.brand_relative_pos}% im Text, Zeichen #${d.char_earliness || d.brand_earliness_char})`
    : 'Nicht im Antworttext genannt';

  const citationStr = d.brand_domain_cited === 1 || d.brand_cited === 1
    ? '✅ Offizielle Domain zitiert'
    : (d.has_citations === 1 ? '❌ Nur Fremddomains zitiert' : 'Keine Quellenlinks');

  const compMentions = (d.competitors || []).filter(c => c.mentioned === 1 || c.is_mentioned === 1);
  const compStr = compMentions.length > 0
    ? compMentions.map(c => `${c.competitor_name || c.name} (Wort #${c.word_earliness || c.earliness_word})`).join(', ')
    : 'Keine getrackten Wettbewerber gefunden';

  const rows = [
    isFailed ? '### ⚠️ Chatlytics AI Visibility Audit (Run Failed)' : '### 📊 Chatlytics AI Visibility Audit',
    '| Metric | Value |',
    '|---|---|',
    `| **Query** | *${d.prompt || ''}* |`,
    `| **Brand** | **${d.brand_name || ''}** |`,
    `| **Getrackte Marke** | **${d.brand_name || ''}** (${brandDomains}) |`,
    `| **Provider** | ${d.provider || ''}${euTag} |`,
    `| **Modell / Provider** | ${d.provider || ''} (${d.model || ''})${euTag} |`,
    `| **Execution Status** | ${d.status || 'completed'} |`,
    `| **MECE Status** | ${d.mece_category} ${meceBadge} |`,
    `| **MECE-Status** | ${d.mece_category} ${meceBadge} |`,
    `| **GEO Diagnostic** | ${d.geo_quadrant} |`,
    `| **GEO-Diagnostik** | ${d.geo_quadrant} — ${geoBadge} |`,
    `| **Brand Earliness** | ${earlinessStr} |`,
    `| **Grounding Citation** | ${citationStr} |`,
    `| **Wettbewerber** | ${compStr} |`
  ];

  if (isFailed && d.error_message) {
    rows.push(`| **Error** | ${d.error_message} |`);
  }

  rows.push('');
  rows.push(`*Antwortlänge: ${d.total_words || 0} Wörter (${d.total_chars || 0} Zeichen) • Ausführungszeit: ${d.run_duration_ms || 0}ms*`);

  const markdown = rows.join('\n');

  output.push({
    json: {
      ...d,
      output: markdown,
      text: markdown,
      response: markdown,
      message: markdown
    }
  });
}

return output;
